*{box-sizing:border-box}html{min-width:320px;-webkit-text-size-adjust:100%}body{margin:0;min-width:320px;overflow:hidden;color:var(--ef-text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:#E8EDF2}button,input{font:inherit}.ef-page{min-height:100vh;display:grid;place-items:center;padding:24px;background:linear-gradient(135deg,#E8EDF2,#F5F5F5)}.ef-shell{position:relative;width:min(100%,390px);height:min(820px,calc(100vh - 48px));min-height:620px;display:flex;align-items:center;justify-content:center;padding:74px 24px 30px;overflow:hidden;border-radius:42px;background:linear-gradient(160deg,rgba(32,41,64,.72),rgba(31,21,12,.78)),url("<?= base_url('assets/images/efactor-ecosystem.jpg') ?>") center bottom/cover no-repeat;box-shadow:0 32px 80px rgba(32,41,64,.24)}.ef-shell::before{content:"";position:absolute;inset:8px;border-radius:34px;background:linear-gradient(to bottom,rgba(0,0,0,.10),rgba(0,0,0,.10) 35%,rgba(0,0,0,.36));pointer-events:none}.ef-shell::after{content:"";position:absolute;z-index:5;top:8px;left:50%;width:112px;height:27px;transform:translateX(-50%);border-radius:0 0 18px 18px;background:#101813}.ef-back{position:absolute;z-index:6;top:30px;left:22px;width:42px;height:42px;display:grid;place-items:center;border:1px solid var(--ef-line);border-radius:50%;color:#fff;background:rgba(255,255,255,.12);backdrop-filter:blur(16px);text-decoration:none;box-shadow:0 12px 30px rgba(0,0,0,.18)}.ef-back svg{width:18px;height:18px}.ef-brand{position:absolute;z-index:6;top:34px;right:24px}.ef-brand img{max-width:108px;max-height:38px;object-fit:contain;border-radius:8px}.ef-scroll{position:relative;z-index:3;width:100%;max-height:100%;overflow-y:auto;overflow-x:hidden;padding:4px 0 2px;scrollbar-width:none}.ef-scroll::-webkit-scrollbar{width:0;height:0}.ef-card{width:100%;padding:24px 22px 21px;border:1px solid var(--ef-line);border-radius:28px;background:var(--ef-panel);box-shadow:0 24px 70px rgba(0,0,0,.32),inset 0 1px 0 rgba(255,255,255,.14);backdrop-filter:blur(22px);animation:efRise .45s ease both}.ef-heading-wrap{text-align:left;margin-bottom:18px}.ef-title{margin:0;color:#fff;font-size:1.92rem;line-height:1.05;font-weight:850;letter-spacing:0}.ef-subtitle{margin:8px 0 0;color:var(--ef-muted);font-size:.76rem;line-height:1.45}.ef-field{margin-bottom:10px}.ef-input{min-height:46px;display:flex;align-items:center;gap:10px;padding:0 13px;border:1px solid rgba(255,255,255,.16);border-radius:12px;background:rgba(255,255,255,.10);box-shadow:inset 0 1px 0 rgba(255,255,255,.08);transition:border-color .2s ease,background .2s ease,box-shadow .2s ease}.ef-input:focus-within{border-color:rgba(232,237,242,.56);background:rgba(255,255,255,.16);box-shadow:0 0 0 4px rgba(232,237,242,.10)}.ef-input.has-error{border-color:rgba(252,165,165,.7);background:rgba(127,29,29,.20)}.ef-icon{width:18px;height:18px;flex:0 0 18px;color:#E8EDF2}.ef-control{flex:1;width:100%;min-width:0;border:0;outline:0;padding:12px 0;color:#fff;background:transparent;font-size:.8rem}.ef-control::placeholder{color:rgba(248,250,252,.62)}.ef-toggle{width:32px;height:32px;display:grid;place-items:center;padding:0;border:0;border-radius:50%;color:#E8EDF2;background:transparent;cursor:pointer}.ef-toggle svg{width:17px;height:17px}.ef-error{min-height:13px;margin-top:3px;color:var(--ef-danger);font-size:.65rem}.ef-send-otp{display:flex;width:100%;min-height:40px;margin:8px 0 0;align-items:center;justify-content:center;color:#fff;font-size:.82rem;font-weight:850;text-decoration:none;border:1px solid rgba(255,255,255,.55);border-radius:14px;background:rgba(255,255,255,.18);padding:8px 12px;cursor:pointer}.ef-password-block{display:none}.ef-password-block.is-visible{display:block}.ef-send-otp:hover{background:rgba(255,255,255,.18)}.ef-otp-badge{display:none;width:max-content;margin:5px 0 0 auto;padding:4px 8px;border-radius:999px;color:#DCFCE7;background:rgba(22,101,52,.26);border:1px solid rgba(134,239,172,.35);font-size:.6rem;font-weight:850}.ef-otp-badge.is-visible{display:block}.ef-otp{display:none;margin:0 0 10px}.ef-otp.is-visible{display:block}.ef-otp-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:7px;color:var(--ef-muted);font-size:.64rem;font-weight:800}.ef-verify-otp{display:none;width:100%;min-height:40px;margin-top:8px;align-items:center;justify-content:center;border:1px solid rgba(255,255,255,.55);border-radius:14px;color:#fff;background:rgba(255,255,255,.18);padding:8px 12px;font-size:.82rem;font-weight:850;cursor:pointer}.ef-otp .ef-send-otp{margin-top:10px}.ef-verify-otp.is-visible{display:inline-flex}.ef-verify-otp.is-verified{border-color:rgba(134,239,172,.45);color:#DCFCE7;background:rgba(22,101,52,.25)}.ef-otp-boxes{display:grid;grid-template-columns:repeat(6,1fr);gap:7px}.ef-otp-box{width:100%;aspect-ratio:1;border:1px solid rgba(255,255,255,.22);border-radius:9px;background:rgba(255,255,255,.12);text-align:center;color:#fff;font-size:1rem;font-weight:850;outline:0}.ef-otp-box:focus{border-color:rgba(232,237,242,.68);box-shadow:0 0 0 3px rgba(232,237,242,.10)}.ef-meter{height:4px;margin-top:5px;overflow:hidden;border-radius:99px;background:rgba(255,255,255,.16)}.ef-meter span{display:block;width:0;height:100%;border-radius:inherit;transition:.25s ease}.ef-meter-row{display:flex;justify-content:space-between;gap:9px;margin-top:4px;color:var(--ef-muted);font-size:.56rem}.ef-terms{display:grid;grid-template-columns:18px 1fr;gap:8px;align-items:start;margin:0 0 12px;color:var(--ef-muted);font-size:.65rem;line-height:1.45}.ef-terms input{width:15px;height:15px;margin:1px 0 0;accent-color:#FFFFFF;color-scheme:dark}.ef-link{color:#fff;font-weight:850;text-decoration:none}.ef-link:hover{text-decoration:underline}.ef-submit{width:100%;min-height:49px;display:flex;align-items:center;justify-content:center;gap:8px;border:1px solid rgba(255,255,255,.2);border-radius:14px;color:#fff;background:linear-gradient(135deg,#202940,#1F