<script>
document.addEventListener('DOMContentLoaded',function(){var password=document.getElementById('password');var confirmPassword=document.getElementById('confirm_password');var meterBar=document.getElementById('passwordMeterBar');var strengthLabel=document.getElementById('passwordStrength');var form=document.getElementById('signupForm');var phone=document.getElementById('phone');var sendOtpButton=document.getElementById('sendOtpButton');var otpSection=document.getElementById('otpSection');var verifyOtpButton=document.getElementById('verifyOtpButton');var otpHidden=document.getElementById('otp');var phoneVerified=document.getElementById('phone_verified');var otpBoxes=[].slice.call(document.querySelectorAll('.ef-otp-box'));function phoneDigits(){return phone?phone.value.replace(/\D/g,'').slice(0,10):''}function showOtp(){if(!otpSection)return;otpSection.classList.add('is-visible');if(sendOtpButton)sendOtpButton.style.display='none'}function syncOtp(){if(otpHidden)otpHidden.value=otpBoxes.map(function(box){return box.value}).join('');if(verifyOtpButton){if(otpHidden.value.length===6){verifyOtpButton.classList.add('is-visible')}else{verifyOtpButton.classList.remove('is-visible','is-verified');verifyOtpButton.textContent='Verify';if(phoneVerified)phoneVerified.value='0'}}}function updatePhone(){if(!phone)return;phone.value=phoneDigits()}function getScore(v){var s=0;if(v.length>=8)s++;if(/[A-Z]/.test(v))s++;if(/[a-z]/.test(v))s++;if(/[0-9]/.test(v))s++;if(/[^A-Za-z0-9]/.test(v))s++;return s}function updateMeter(){if(!password||!meterBar||!strengthLabel)return;var score=getScore(password.value);var widths=['0%','20%','40%','60%','80%','100%'];var labels=['Password strength','Very weak','Weak','Fair','Strong','Excellent'];var colors=['rgba(255,255,255,.18)','#EF4444','#F97316','#F59E0B','#22C55E','#16A34A'];meterBar.style.width=widths[score];meterBar.style.background=colors[score];strengthLabel.textContent=labels[score];strengthLabel.style.color=colors[score]}function checkMatch(){var error=document.getElementById('confirmPasswordError');if(!confirmPassword||!password)return;if(confirmPassword.value&&confirmPassword.value!==password.value){confirmPassword.setCustomValidity('Passwords do not match.');if(error&&!error.textContent.trim())error.textContent='Passwords do not match.'}else{confirmPassword.setCustomValidity('');if(error&&error.textContent.trim()==='Passwords do not match.')error.textContent=''}}if(phone)phone.addEventListener('input',updatePhone);function requestOtp(){if(phone&&phone.value.length===10){showOtp();var cfg=window.SD_AUTH||{};if(cfg.otpUrl){var body=new URLSearchParams();body.append('phone',phone.value);if(cfg.csrfName&&cfg.csrfHash)body.append(cfg.csrfName,cfg.csrfHash);fetch(cfg.otpUrl,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','X-Requested-With':'XMLHttpRequest'},body:body.toString()}).then(function(r){return r.json()}).then(function(data){if(data&&data.csrfHash){cfg.csrfHash=data.csrfHash;window.SD_AUTH=cfg}}).catch(function(){})}if(otpBoxes[0])otpBoxes[0].focus()}else if(phone){phone.focus();phone.reportValidity&&phone.reportValidity()}}if(sendOtpButton)sendOtpButton.addEventListener('click',requestOtp);var resendOtpButton=document.getElementById('resendOtpButton');if(resendOtpButton)resendOtpButton.addEventListener('click',requestOtp);otpBoxes.forEach(function(box,index){box.addEventListener('input',function(){box.value=box.value.replace(/\D/g,'').slice(0,1);syncOtp();if(box.value&&otpBoxes[index+1])otpBoxes[index+1].focus()});box.addEventListener('keydown',function(event){if(event.key==='Backspace'&&!box.value&&otpBoxes[index-1])otpBoxes[index-1].focus()})});if(verifyOtpButton)verifyOtpButton.addEventListener('click',function(){syncOtp();if(otpHidden&&otpHidden.value.length===6){verifyOtpButton.textContent='Verified';verifyOtpButton.classList.add('is-verified');if(phoneVerified)phoneVerified.value='1';var passwordBlock=document.getElementById('passwordBlock');if(passwordBlock)passwordBlock.classList.add('is-visible')}});if(password)password.addEventListener('input',function(){updateMeter();checkMatch()});if(confirmPassword)confirmPassword.addEventListener('input',checkMatch);document.querySelectorAll('[data-password-toggle]').forEach(function(button){button.addEventListener('click',function(){var input=document.getElementById(button.dataset.passwordToggle);if(!input)return;var show=input.type==='password';input.type=show?'text':'password';button.setAttribute('aria-label',show?'Hide password':'Show password')})});if(form)form.addEventListener('submit',function(){checkMatch();syncOtp();if(!form.checkValidity())return;var label=form.querySelector('.button-label');var spinner=form.querySelector('.spinner-border');if(label)label.textContent='Creating account...';if(spinner)spinner.classList.remove('d-none');var submit=document.getElementById('submitButton');if(submit)submit.disabled=true});updatePhone();updateMeter();syncOtp();var passwordBlock=document.getElementById('passwordBlock');var passwordError=passwordBlock?passwordBlock.querySelector('.ef-error'):null;if(passwordBlock&&((password&&password.value)||(confirmPassword&&confirmPassword.value)||(passwordError&&passwordError.textContent.trim())))passwordBlock.classList.add('is-visible')});
</script>
